text:
Here's your water tracker. Tap a glass to fill it, and your count and progress update as you go. The goal is 8 glasses a day.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Water tracker</title>
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:24px;background:#eef6fb;color:#12344d;text-align:center}
  h1{font-size:22px;margin:0 0 4px}
  #count{font-size:48px;font-weight:600;margin:12px 0 0}
  #msg{margin:4px 0 16px;min-height:22px}
  #bar{height:12px;background:#d3e6f2;border-radius:6px;max-width:360px;margin:0 auto 20px;overflow:hidden}
  #fill{height:100%;width:0;background:#2a8fd0;transition:width .3s}
  #glasses{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;max-width:360px;margin:0 auto 20px}
  .g{height:64px;border:2px solid #2a8fd0;border-radius:6px 6px 14px 14px;background:#fff;cursor:pointer;font-size:26px}
  .g.on{background:#2a8fd0;color:#fff}
  button.c{font-size:16px;padding:8px 16px;margin:0 4px;border:0;border-radius:6px;background:#12344d;color:#fff;cursor:pointer}
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <button class="c" id="minus">− One</button>
  <button class="c" id="plus">+ One</button>
  <button class="c" id="reset">Reset</button>
<script>
  var GOAL = 8, n = 0;
  var key = "water-" + new Date().toISOString().slice(0,10);
  try { n = parseInt(localStorage.getItem(key)) || 0; } catch(e) {}
  document.getElementById("date").textContent = new Date().toDateString();
  var wrap = document.getElementById("glasses");
  for (var i = 0; i < GOAL; i++) {
    (function(i){
      var b = document.createElement("div");
      b.className = "g";
      b.onclick = function(){ set(n === i + 1 ? i : i + 1); };
      wrap.appendChild(b);
    })(i);
  }
  function set(v) {
    n = Math.max(0, Math.min(GOAL, v));
    try { localStorage.setItem(key, n); } catch(e) {}
    draw();
  }
  function draw() {
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = (n / GOAL * 100) + "%";
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " more to go";
    var gs = wrap.children;
    for (var i = 0; i < gs.length; i++) {
      gs[i].className = "g" + (i < n ? " on" : "");
      gs[i].textContent = i < n ? "💧" : "";
    }
  }
  document.getElementById("plus").onclick = function(){ set(n + 1); };
  document.getElementById("minus").onclick = function(){ set(n - 1); };
  document.getElementById("reset").onclick = function(){ set(0); };
  draw();
</script>
</body>
</html>
```
